def raster(polygons, shape=(720,556)):
    mask=np.zeros(shape,np.uint8)
    for polygon in polygons: cv2.fillPoly(mask,[points(polygon)],255)
    return mask

def make_mask(pixels, polygons, frame, background):
    cv2.setRNGSeed(frame)
    mask=raster(polygons)
    # Only a narrow band around the reviewed outlines may be classified again.
    inner=cv2.erode(mask,np.ones((23,23),np.uint8))
    outer=cv2.dilate(mask,np.ones((19,19),np.uint8))
    labels=np.full(mask.shape,cv2.GC_BGD,np.uint8)
    labels[outer>0]=cv2.GC_PR_BGD
    labels[mask>0]=cv2.GC_PR_FGD
    labels[inner>0]=cv2.GC_FGD
    delta=np.max(np.abs(pixels.astype(np.int16)-background.astype(np.int16)),axis=2)>4
    protected=(delta & (mask>0));protected[:,:125]=False
    labels[protected]=cv2.GC_FGD
    # The small ears and metal fingers must not disappear into the dark room.
    ear_indices={242:[0],243:[1],396:[1],397:[0,2]}.get(frame,[0,2])
    for index in ear_indices:
        ear=cv2.erode(raster([polygons[index]]),np.ones((5,5),np.uint8))
        labels[ear>0]=cv2.GC_FGD
    cv2.grabCut(pixels,labels,None,np.zeros((1,65),np.float64),np.zeros((1,65),np.float64),3,cv2.GC_INIT_WITH_MASK)
    result=np.uint8((labels==cv2.GC_FGD)|(labels==cv2.GC_PR_FGD))*255
    # The room is static outside the initially occluded left edge. Remove matching
    # room pixels from the outline band, retaining the character's solid interior.
    stable_inner=cv2.erode(mask,np.ones((5,5),np.uint8))>0
    trim=(~delta)&(mask==0)
    trim[:190]|=(~delta[:190])&(~stable_inner[:190])
    trim[:,:125]=False
    result[trim]=0
    if frame==396: result[260:306,166:175]=0
    if frame==397: result[280:312,175:195]=0
    return result

def main():
    out=Path(sys.argv[1]) if len(sys.argv)>1 else None
    paths=[]
    background=np.asarray(Image.open(ROOT/'assets/sources/fnaf1/242.png').convert('RGB').crop((94,0,650,720)))
    for file in sorted((ROOT/'assets/sources/fnaf1').glob('*.png'),key=lambda p:int(p.stem)):
        n=int(file.stem)
        image=Image.open(file).convert('RGB').crop((94,0,650,720))
        pixels=np.asarray(image)
        polygons=HEADS[n]+EARLY_BODIES.get(n,[BODY,ARM])
        if n in CAPS: polygons=polygons+[CAPS[n]]
        if n in NECKS: polygons=polygons+[NECKS[n]]
        mask=make_mask(pixels,polygons,n,background)
        contours,_=cv2.findContours(mask,cv2.RETR_LIST,cv2.CHAIN_APPROX_SIMPLE)
        paths.append(''.join('M'+'L'.join(f'{x},{y}' for x,y in cv2.approxPolyDP(c,.35,True)[:,0])+'Z' for c in contours if cv2.contourArea(c)>8))
        if out:
            preview=np.full_like(pixels,100);preview[mask>0]=pixels[mask>0]
            Image.fromarray(preview).save(out/f'classic-{n}.png')
        print(n,flush=True)
    (ROOT/'assets/fnaf1-foxy-masks.json').write_text(json.dumps(paths),encoding='utf-8')

if __name__=='__main__': main()
